import itertools
import numpy as np

def hamming_distance(s1, s2):
    """Calculates the Hamming distance between two binary strings."""
    return sum(c1 != c2 for c1, c2 in zip(s1, s2))

def generate_sphere(L, n, k):
    """Generates the set A(L, k) of all strings at distance k from L."""
    A_L_k = set()
    # Iterate over all possible strings M of length n
    for M_tuple in itertools.product([0, 1], repeat=n):
        M = "".join(map(str, M_tuple))
        if hamming_distance(L, M) == k:
            A_L_k.add(M)
    return A_L_k

def search_counterexamples(n, k):
    print(f"--- Searching for counterexamples for n={n}, k={k} ---")

    # Generate all possible binary strings of length n
    all_strings = ["".join(map(str, p)) for p in itertools.product([0, 1], repeat=n)]

    counterexamples_found = []

    # Key: frozenset(A(L, k)), Value: list of L strings
    sets_map = {}

    for L1 in all_strings:
        # Optimization: Only compute the set once per unique L1
        A_L1_k = generate_sphere(L1, n, k)

        if frozenset(A_L1_k) not in sets_map:
            sets_map[frozenset(A_L1_k)] = []

        sets_map[frozenset(A_L1_k)].append(L1)

    # Identify sets that contain more than one unique string L
    for A_set, L_list in sets_map.items():
        if len(L_list) > 1:
            print(f"\n[!!!] COUNTEREXAMPLE FOUND for n={n}, k={k}!")

            # Check all pairs in the list
            for i in range(len(L_list)):
                for j in range(i + 1, len(L_list)):
                    L1 = L_list[i]
                    L2 = L_list[j]
                    d = hamming_distance(L1, L2)
                    counterexamples_found.append((L1, L2, d))
                    print(f"  Pair found: L1={L1}, L2={L2}, Distance d={d}")

            # Since the task only asks for *a* counterexample and its distance, we stop.
            return counterexamples_found[0]

    if not counterexamples_found:
        print(f"No counterexamples found for n={n}, k={k}.")

    return []

# --- Testing Case k=5, n=11 ---
k = 5
n = 2 * k + 1
results_k5 = search_counterexamples(n, k)

if results_k5:
    _, _, d = results_k5
    print(f"\nCounterexample found for n=11, k=5. The distance d(L1, L2) is: {d}")
else:
    print("\nNo counterexamples found for n=11, k=5.")
